```tsx
import { useId, type ChangeEvent, type FormEvent } from "react";
import "./CommandBox.css";

export interface CommandReply {
  text: string;
  isError?: boolean;
}

export interface CommandBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  reply?: CommandReply;
}

export function CommandBox({ value, onChange, onSubmit, reply }: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    onChange(event.currentTarget.value);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit(value);
  }

  return (
    <div className="command-box">
      <form className="command-box__form" onSubmit={handleSubmit}>
        <label className="sr-only" htmlFor={inputId}>
          Command
        </label>
        <input
          id={inputId}
          className="command-box__input"
          type="text"
          value={value}
          placeholder="Type a command, for example: log 20 min reading"
          autoComplete="off"
          spellCheck={false}
          aria-describedby={reply ? replyId : undefined}
          onChange={handleChange}
        />
        <button type="submit" className="command-box__submit">
          Run
        </button>
      </form>

      <div className="command-box__reply-slot">
        {reply && (
          <div
            id={replyId}
            className={
              reply.isError
                ? "command-box__reply command-box__reply--error"
                : "command-box__reply command-box__reply--normal"
            }
            role={reply.isError ? "alert" : "status"}
          >
            {reply.text}
          </div>
        )}
      </div>
    </div>
  );
}
```

